import { world, system, ItemStack } from "@minecraft/server";

// "The Deep Sky" — Bedrock cannot define real custom dimensions, so this is a
// pocket world emulated far out in The End (which has no day/night cycle):
// floating deep-dark islands generated by script on first arrival.
//
// Entry: use a Teleport Waypoint while the Slow Falling effect is active
//        (a vanilla Potion of Slow Falling, brewed from phantom membrane).
// Stay:  as long as that effect lasts; another potion simply extends it.
// Exit:  the moment the effect is gone the visitor is pulled back.
export const DEEPSKY_CONFIG = {
  name: "The Deep Sky",
  dimensionId: "minecraft:the_end",
  center: { x: 100000, y: 190, z: 100000 },
  bounds: 160,              // horizontal half-size of the zone
  floorY: 130,              // fall below this and you are lifted back to the arrival pad
  effectId: "slow_falling",
  minVisaTicks: 600,        // a visit lasts at least 30 s, even from a nearly spent potion
  maxEffectTicks: 20000000,
  fogId: "wp:deep_sky",
  fogSlot: "wpdeepsky",
  wardens: { everyTicks: 100, chance: 0.008, maxNearby: 1, radius: 64 }
};

const VISITOR_PROP = "wp:deepsky";
const BUILT_PROP = "wp:deepsky/built";
const BLOCK_ID = "wp:waypoint";

// ---------------------------------------------------------------------------
// Public API
// ---------------------------------------------------------------------------

export function initDeepSky() {
  const cfg = DEEPSKY_CONFIG;

  system.runInterval(visitorTick, 10);
  // Also sweep without visitors: old saved entities can load later, and a
  // phantom can enter the zone without triggering a new spawn event.
  system.run(removeDeepSkyPhantoms);
  system.runInterval(removeDeepSkyPhantoms, 20);

  // No rest and no new spawn point up there: beds and respawn anchors are inert.
  world.beforeEvents.playerInteractWithBlock.subscribe((ev) => {
    try {
      const id = ev.block.typeId;
      if (id !== "minecraft:bed" && id !== "minecraft:respawn_anchor") return;
      const player = ev.player;
      if (!readVisitor(player)) return;
      ev.cancel = true;
      system.run(() => {
        try {
          player.sendMessage("§cThere is no rest in The Deep Sky.");
        } catch {}
      });
    } catch {}
  });

  // Keep natural endermen and any newly spawned phantoms out of the pocket.
  world.afterEvents.entitySpawn.subscribe((ev) => {
    try {
      const entity = ev.entity;
      if (entity.dimension.id !== cfg.dimensionId) return;
      if (entity.typeId === "minecraft:phantom" && isInDeepSky(entity.dimension.id, entity.location)) {
        entity.remove();
      } else if (entity.typeId === "minecraft:enderman" && inZone(entity.location)) {
        entity.remove();
      }
    } catch {}
  });

  // Dying ends the visit; the respawn happens wherever the player normally spawns.
  const pendingFog = new Set();
  world.afterEvents.entityDie.subscribe((ev) => {
    try {
      const entity = ev.deadEntity;
      if (entity.typeId !== "minecraft:player" || !readVisitor(entity)) return;
      entity.setDynamicProperty(VISITOR_PROP, undefined);
      pendingFog.add(entity.id);
    } catch {}
  });
  world.afterEvents.playerSpawn.subscribe((ev) => {
    try {
      if (!pendingFog.has(ev.player.id)) return;
      pendingFog.delete(ev.player.id);
      removeFog(ev.player);
    } catch {}
  });
}

export function isDeepSkyVisitor(player) {
  try {
    return !!readVisitor(player);
  } catch {
    return false;
  }
}

export function isInDeepSky(dimensionId, location) {
  const cfg = DEEPSKY_CONFIG;
  return (
    dimensionId === cfg.dimensionId &&
    Math.abs(location.x - cfg.center.x) <= cfg.bounds &&
    Math.abs(location.z - cfg.center.z) <= cfg.bounds
  );
}

export function hasEntryEffect(player) {
  try {
    return !!player.getEffect(DEEPSKY_CONFIG.effectId);
  } catch {
    return false;
  }
}

// origin: { ox, oy, oz, odim, oname } — the waypoint the player left from.
export function enterDeepSky(player, origin) {
  const cfg = DEEPSKY_CONFIG;
  // A nearly spent potion still buys the minimum visit.
  const effect = player.getEffect(cfg.effectId);
  const remaining = effect ? effect.duration : 0;
  if (remaining < cfg.minVisaTicks) {
    player.addEffect(cfg.effectId, cfg.minVisaTicks, { amplifier: effect ? effect.amplifier : 0, showParticles: true });
  }
  player.setDynamicProperty(VISITOR_PROP, JSON.stringify(origin));

  const arrival = arrivalPoint();
  player.teleport({ x: arrival.x, y: arrival.y + 3, z: arrival.z }, { dimension: skyDimension() });
  waitForArrival(player);

  system.runTimeout(() => {
    try {
      player.runCommand(`fog @s push ${cfg.fogId} ${cfg.fogSlot}`);
    } catch {}
    try {
      player.playSound("mob.shulker.teleport");
      player.onScreenDisplay.setTitle(`§8${cfg.name}`, {
        subtitle: "§7There is no dawn here.",
        fadeInDuration: 10,
        stayDuration: 70,
        fadeOutDuration: 20
      });
      player.sendMessage(
        `§d${cfg.name}: §7you will be pulled back to "§f${origin.oname}§7" the moment your Slow Falling fades. ` +
          "Another Potion of Slow Falling prolongs the stay."
      );
    } catch {}
  }, 10);
}

// ---------------------------------------------------------------------------
// Visitor bookkeeping
// ---------------------------------------------------------------------------

function readVisitor(player) {
  const raw = player.getDynamicProperty(VISITOR_PROP);
  if (typeof raw !== "string") return undefined;
  try {
    return JSON.parse(raw);
  } catch {
    return undefined;
  }
}

function skyDimension() {
  return world.getDimension(DEEPSKY_CONFIG.dimensionId);
}

function arrivalPoint() {
  const c = DEEPSKY_CONFIG.center;
  return { x: c.x + 0.5, y: c.y + 1, z: c.z + 0.5 };
}

function inZone(location) {
  const cfg = DEEPSKY_CONFIG;
  return (
    Math.abs(location.x - cfg.center.x) <= cfg.bounds &&
    Math.abs(location.z - cfg.center.z) <= cfg.bounds &&
    location.y >= cfg.floorY
  );
}

function removeFog(player) {
  try {
    player.runCommand(`fog @s remove ${DEEPSKY_CONFIG.fogSlot}`);
  } catch {}
}

let tickCount = 0;

function visitorTick() {
  tickCount += 10;
  let players;
  try {
    players = world.getAllPlayers();
  } catch {
    return;
  }
  let anyVisitor = false;
  for (const player of players) {
    let visitor;
    try {
      visitor = readVisitor(player);
    } catch {
      continue;
    }
    if (!visitor) continue;
    anyVisitor = true;
    try {
      tickVisitor(player, visitor);
    } catch {}
  }
  if (anyVisitor && tickCount % 40 === 0) ensureBuilt();
}

function tickVisitor(player, visitor) {
  const cfg = DEEPSKY_CONFIG;

  if (!player.getEffect(cfg.effectId)) {
    returnHome(player, visitor);
    return;
  }

  if (player.dimension.id !== cfg.dimensionId || !inZone(player.location)) {
    player.teleport(arrivalPoint(), { dimension: skyDimension() });
    player.sendMessage("§dThe Deep Sky draws you back to its heart.");
    return;
  }

  if (tickCount % cfg.wardens.everyTicks === 0) maybeSpawnWarden(player);
}

function returnHome(player, visitor) {
  player.setDynamicProperty(VISITOR_PROP, undefined);
  removeFog(player);
  let dimension;
  try {
    dimension = world.getDimension(visitor.odim);
  } catch {
    dimension = world.getDimension("minecraft:overworld");
  }
  player.teleport({ x: visitor.ox + 0.5, y: visitor.oy + 1, z: visitor.oz + 0.5 }, { dimension });
  player.sendMessage(`§bThe potion fades — you are pulled back to "§f${visitor.oname}§b".`);
  try {
    player.playSound("mob.shulker.teleport");
  } catch {}
}

// The arrival chunk loads a few ticks after the teleport; put a pad under the
// player as soon as it does, then let the full build job take over.
function waitForArrival(player) {
  const cfg = DEEPSKY_CONFIG;
  const c = cfg.center;
  let tries = 0;
  const handle = system.runInterval(() => {
    tries++;
    let probe;
    try {
      probe = skyDimension().getBlock({ x: c.x, y: c.y, z: c.z });
    } catch {
      probe = undefined;
    }
    if (!probe && tries < 200) return;
    system.clearRun(handle);
    if (!probe) return;
    try {
      const dim = skyDimension();
      for (let x = -2; x <= 2; x++) {
        for (let z = -2; z <= 2; z++) setBlock(dim, c.x + x, c.y, c.z + z, "minecraft:polished_deepslate");
      }
      if (player.location.y < c.y + 0.5) player.teleport(arrivalPoint(), { dimension: dim });
    } catch {}
    ensureBuilt();
  }, 1);
}

// ---------------------------------------------------------------------------
// Hostiles
// ---------------------------------------------------------------------------

function removeDeepSkyPhantoms() {
  let phantoms;
  try {
    phantoms = skyDimension().getEntities({ type: "minecraft:phantom" });
  } catch {
    return;
  }
  for (const phantom of phantoms) {
    try {
      // All heights are covered, including below the visitor rescue floor.
      if (isInDeepSky(phantom.dimension.id, phantom.location)) phantom.remove();
    } catch {}
  }
}

function maybeSpawnWarden(player) {
  const cfg = DEEPSKY_CONFIG.wardens;
  if (Math.random() >= cfg.chance) return;
  const dim = player.dimension;
  const loc = player.location;
  const nearby = dim.getEntities({ location: loc, maxDistance: cfg.radius, type: "minecraft:warden" }).length;
  if (nearby >= cfg.maxNearby) return;
  const spot = findGroundSpot(dim, loc, 8, 24);
  if (!spot) return;
  try {
    dim.spawnEntity("minecraft:warden", spot);
    dim.playSound("mob.warden.emerge", spot);
    player.sendMessage("§8Something stirs beneath the sculk...");
  } catch {}
}

function findGroundSpot(dim, around, minR, maxR) {
  for (let attempt = 0; attempt < 12; attempt++) {
    const angle = Math.random() * Math.PI * 2;
    const r = minR + Math.random() * (maxR - minR);
    const x = Math.floor(around.x + Math.cos(angle) * r);
    const z = Math.floor(around.z + Math.sin(angle) * r);
    const top = Math.floor(around.y) + 4;
    for (let y = top; y > top - 34; y--) {
      let block;
      try {
        block = dim.getBlock({ x, y, z });
      } catch {
        block = undefined;
      }
      if (!block) break;
      if (block.isAir) continue;
      const above = dim.getBlock({ x, y: y + 1, z });
      const above2 = dim.getBlock({ x, y: y + 2, z });
      if (above?.isAir && above2?.isAir) return { x: x + 0.5, y: y + 1, z: z + 0.5 };
      break;
    }
  }
  return undefined;
}

// ---------------------------------------------------------------------------
// World generation
// ---------------------------------------------------------------------------

// Island layout relative to the centre. Everything stays within ±48 blocks so
// it is inside simulation distance of the arrival pad while being built.
const ISLANDS = [
  { dx: 0, dz: 0, dy: 0, rx: 19, rz: 17, depth: 15, kind: "citadel" },
  { dx: 38, dz: 6, dy: 0, rx: 9, rz: 8, depth: 8, kind: "tower" },
  { dx: -36, dz: -10, dy: 0, rx: 10, rz: 8, depth: 8, kind: "garden" },
  { dx: 8, dz: 38, dy: 0, rx: 8, rz: 9, depth: 7, kind: "ruin" },
  { dx: -12, dz: -38, dy: 0, rx: 8, rz: 8, depth: 7, kind: "shrine" },
  { dx: 30, dz: -30, dy: -12, rx: 6, rz: 6, depth: 5, kind: "islet" },
  { dx: -30, dz: 32, dy: -14, rx: 6, rz: 6, depth: 5, kind: "islet" }
];
const BRIDGES = [
  [0, 1],
  [0, 2],
  [0, 3],
  [0, 4]
];

const KNOWN_BAD_BLOCKS = new Set();

function setBlock(dim, x, y, z, id) {
  try {
    dim.setBlockType({ x, y, z }, id);
    return true;
  } catch (e) {
    if (!KNOWN_BAD_BLOCKS.has(id)) {
      KNOWN_BAD_BLOCKS.add(id);
      console.warn(`[Waypoint] Deep Sky: could not place ${id} (${e})`);
    }
    return false;
  }
}

// Deterministic 0..1 hash so the terrain looks the same on every rebuild.
function noise(x, z) {
  let h = (Math.imul(x | 0, 374761393) + Math.imul(z | 0, 668265263)) | 0;
  h = Math.imul(h ^ (h >>> 13), 1274126177) | 0;
  return ((h ^ (h >>> 16)) >>> 0) / 4294967296;
}

function loadBuilt() {
  try {
    const raw = world.getDynamicProperty(BUILT_PROP);
    if (typeof raw === "string") {
      const list = JSON.parse(raw);
      if (Array.isArray(list)) return list;
    }
  } catch {}
  return [];
}

function saveBuilt(list) {
  try {
    world.setDynamicProperty(BUILT_PROP, JSON.stringify(list));
  } catch {}
}

let building = false;

function ensureBuilt() {
  if (building) return;
  const built = loadBuilt();
  if (built.length >= ISLANDS.length + BRIDGES.length) return;
  building = true;
  try {
    system.runJob(buildJob(built));
  } catch {
    building = false;
  }
}

function* buildJob(built) {
  try {
    const dim = skyDimension();
    const c = DEEPSKY_CONFIG.center;
    for (let i = 0; i < ISLANDS.length; i++) {
      if (built.includes(i)) continue;
      const isl = ISLANDS[i];
      const cx = c.x + isl.dx, cy = c.y + isl.dy, cz = c.z + isl.dz;
      if (!isLoaded(dim, cx, cy, cz)) continue;
      yield* buildIsland(dim, cx, cy, cz, isl);
      built.push(i);
      saveBuilt(built);
    }
    for (let b = 0; b < BRIDGES.length; b++) {
      const id = ISLANDS.length + b;
      if (built.includes(id)) continue;
      const [a, bIdx] = BRIDGES[b];
      if (!built.includes(a) || !built.includes(bIdx)) continue;
      const A = ISLANDS[a], B = ISLANDS[bIdx];
      yield* buildBridge(dim, c.x + A.dx, c.y + A.dy, c.z + A.dz, c.x + B.dx, c.z + B.dz, A, B);
      built.push(id);
      saveBuilt(built);
    }
  } finally {
    building = false;
  }
}

function isLoaded(dim, x, y, z) {
  try {
    return !!dim.getBlock({ x, y, z });
  } catch {
    return false;
  }
}

function bodyBlock(depthFromTop, totalDepth, x, z) {
  if (depthFromTop >= totalDepth * 0.55) return "minecraft:deepslate";
  const n = noise(x * 3 + 7, z * 3 + 11);
  if (n < 0.55) return "minecraft:deepslate";
  if (n < 0.8) return "minecraft:tuff";
  return "minecraft:cobbled_deepslate";
}

function topBlock(x, z, edge) {
  if (edge < 0.14) return noise(x, z) < 0.5 ? "minecraft:cobbled_deepslate" : "minecraft:deepslate";
  const cluster = noise(x >> 2, z >> 2);
  const fine = noise(x, z);
  if (cluster < 0.22 && fine < 0.7) return "minecraft:sculk";
  if (fine < 0.08) return "minecraft:cracked_deepslate_tiles";
  if (fine < 0.14) return "minecraft:cracked_deepslate_bricks";
  if (fine < 0.5) return "minecraft:deepslate_tiles";
  if (fine < 0.78) return "minecraft:deepslate_bricks";
  if (fine < 0.88) return "minecraft:polished_deepslate";
  return "minecraft:cobbled_deepslate";
}

function insideIsland(x, z, isl, cx, cz) {
  const nx = (x - cx) / isl.rx;
  const nz = (z - cz) / isl.rz;
  return 1 - (nx * nx + nz * nz) + (noise(x, z) - 0.5) * 0.35;
}

function* buildIsland(dim, cx, cy, cz, isl) {
  let ops = 0;
  for (let x = -isl.rx; x <= isl.rx; x++) {
    for (let z = -isl.rz; z <= isl.rz; z++) {
      const wx = cx + x, wz = cz + z;
      const edge = insideIsland(wx, wz, isl, cx, cz);
      if (edge <= 0) continue;
      const wobble = (noise(wx + 31, wz + 17) - 0.5) * 2;
      const depth = Math.max(1, Math.round(isl.depth * Math.pow(edge, 0.55) + wobble));
      for (let d = depth; d >= 1; d--) {
        setBlock(dim, wx, cy - d, wz, bodyBlock(d, depth, wx, wz));
        if (++ops % 200 === 0) yield;
      }
      setBlock(dim, wx, cy, wz, topBlock(wx, wz, edge));
      if (++ops % 200 === 0) yield;
    }
  }
  yield* decorate(dim, cx, cy, cz, isl);
}

function pillar(dim, x, y, z, height, block, cap) {
  for (let i = 1; i <= height; i++) setBlock(dim, x, y + i, z, block);
  if (cap) setBlock(dim, x, y + height + 1, z, cap);
}

function scatter(dim, cx, cy, cz, isl, block, count, minR, keepClear) {
  let placed = 0;
  for (let attempt = 0; attempt < count * 6 && placed < count; attempt++) {
    const angle = noise(attempt * 13 + cx, placed * 7 + cz) * Math.PI * 2;
    const r = minR + noise(attempt * 5 + cz, placed * 3 + cx) * (Math.min(isl.rx, isl.rz) - minR - 2);
    const x = Math.round(cx + Math.cos(angle) * r);
    const z = Math.round(cz + Math.sin(angle) * r);
    if (keepClear && Math.abs(x - cx) <= keepClear && Math.abs(z - cz) <= keepClear) continue;
    if (insideIsland(x, z, isl, cx, cz) < 0.2) continue;
    if (setBlock(dim, x, cy + 1, z, block)) placed++;
  }
}

function* decorate(dim, cx, cy, cz, isl) {
  switch (isl.kind) {
    case "citadel": {
      // Arrival pad and the reinforced-deepslate frame the ancient cities are known for.
      for (let x = -2; x <= 2; x++) for (let z = -2; z <= 2; z++) setBlock(dim, cx + x, cy, cz + z, "minecraft:polished_deepslate");
      const fz = cz - 8;
      for (let x = -2; x <= 2; x++) {
        for (let y = 0; y <= 5; y++) {
          const isFrame = x === -2 || x === 2 || y === 0 || y === 5;
          if (isFrame) setBlock(dim, cx + x, cy + 1 + y, fz, "minecraft:reinforced_deepslate");
        }
      }
      for (let x = -1; x <= 1; x++) {
        setBlock(dim, cx + x, cy, fz, "minecraft:soul_soil");
        setBlock(dim, cx + x, cy + 1, fz, "minecraft:soul_fire");
      }
      yield;
      // Ring of lantern pillars.
      for (let i = 0; i < 8; i++) {
        const a = (i / 8) * Math.PI * 2;
        const px = Math.round(cx + Math.cos(a) * 10);
        const pz = Math.round(cz + Math.sin(a) * 9);
        pillar(dim, px, cy, pz, 3 + (i % 2), "minecraft:deepslate_tiles", "minecraft:soul_lantern");
      }
      yield;
      // Broken walls.
      for (let seg = 0; seg < 4; seg++) {
        const a = (seg / 4) * Math.PI * 2 + 0.4;
        const sx = Math.round(cx + Math.cos(a) * 14);
        const sz = Math.round(cz + Math.sin(a) * 12);
        const alongX = seg % 2 === 0;
        for (let i = -3; i <= 3; i++) {
          const wx = alongX ? sx + i : sx;
          const wz = alongX ? sz : sz + i;
          if (insideIsland(wx, wz, isl, cx, cz) < 0.1) continue;
          const h = 1 + Math.floor(noise(wx, wz) * 3);
          for (let y = 1; y <= h; y++) {
            setBlock(dim, wx, cy + y, wz, y === h && noise(wx + 1, wz) < 0.4 ? "minecraft:cracked_deepslate_bricks" : "minecraft:deepslate_bricks");
          }
        }
      }
      yield;
      scatter(dim, cx, cy, cz, isl, "minecraft:sculk_catalyst", 3, 5, 3);
      scatter(dim, cx, cy, cz, isl, "minecraft:sculk_sensor", 4, 4, 3);
      scatter(dim, cx, cy, cz, isl, "minecraft:sculk_shrieker", 1, 6, 3);
      scatter(dim, cx, cy, cz, isl, "minecraft:gray_wool", 5, 6, 3);
      scatter(dim, cx, cy, cz, isl, "minecraft:dark_oak_log", 3, 7, 3);
      yield;
      placeChest(dim, cx + 4, cy + 1, cz + 4);
      break;
    }
    case "tower": {
      for (let y = 1; y <= 7; y++) {
        for (let x = -1; x <= 1; x++) {
          for (let z = -1; z <= 1; z++) {
            const wall = Math.abs(x) === 1 || Math.abs(z) === 1;
            if (!wall) continue;
            const window = y === 4 && (x === 0 || z === 0);
            setBlock(dim, cx + x, cy + y, cz + z, window ? "minecraft:air" : "minecraft:deepslate_bricks");
          }
        }
      }
      setBlock(dim, cx, cy + 8, cz, "minecraft:soul_lantern");
      for (let x = -1; x <= 1; x++) for (let z = -1; z <= 1; z++) setBlock(dim, cx + x, cy + 8, cz + z, "minecraft:deepslate_tile_slab");
      setBlock(dim, cx, cy + 8, cz, "minecraft:soul_lantern");
      setBlock(dim, cx, cy + 1, cz - 1, "minecraft:air");
      yield;
      scatter(dim, cx, cy, cz, isl, "minecraft:sculk_sensor", 2, 3, 1);
      break;
    }
    case "garden": {
      for (let x = -isl.rx; x <= isl.rx; x++) {
        for (let z = -isl.rz; z <= isl.rz; z++) {
          const wx = cx + x, wz = cz + z;
          if (insideIsland(wx, wz, isl, cx, cz) < 0.25) continue;
          if (noise(wx * 2, wz * 2) < 0.55) setBlock(dim, wx, cy, wz, "minecraft:sculk");
        }
      }
      yield;
      scatter(dim, cx, cy, cz, isl, "minecraft:sculk_catalyst", 3, 2, 0);
      scatter(dim, cx, cy, cz, isl, "minecraft:sculk_sensor", 3, 2, 0);
      pillar(dim, cx, cy, cz, 2, "minecraft:polished_basalt", "minecraft:soul_lantern");
      break;
    }
    case "ruin": {
      for (let i = -4; i <= 4; i++) {
        const h = 1 + Math.floor(noise(cx + i, cz) * 3);
        for (let y = 1; y <= h; y++) setBlock(dim, cx + i, cy + y, cz - 3, "minecraft:deepslate_tiles");
        const h2 = 1 + Math.floor(noise(cx, cz + i) * 3);
        for (let y = 1; y <= h2; y++) setBlock(dim, cx + 4, cy + y, cz + i, "minecraft:deepslate_bricks");
      }
      yield;
      scatter(dim, cx, cy, cz, isl, "minecraft:gray_wool", 3, 2, 0);
      scatter(dim, cx, cy, cz, isl, "minecraft:light_blue_wool", 2, 2, 0);
      pillar(dim, cx - 2, cy, cz + 2, 3, "minecraft:dark_oak_log", "minecraft:soul_lantern");
      break;
    }
    case "shrine": {
      for (let x = -2; x <= 2; x++) for (let z = -2; z <= 2; z++) setBlock(dim, cx + x, cy, cz + z, "minecraft:chiseled_deepslate");
      setBlock(dim, cx, cy + 1, cz, "minecraft:sculk_shrieker");
      for (const [ox, oz] of [[-2, -2], [2, -2], [-2, 2], [2, 2]]) {
        pillar(dim, cx + ox, cy, cz + oz, 2, "minecraft:deepslate_tile_wall", "minecraft:soul_lantern");
      }
      yield;
      scatter(dim, cx, cy, cz, isl, "minecraft:sculk_sensor", 3, 3, 2);
      scatter(dim, cx, cy, cz, isl, "minecraft:sculk", 4, 3, 2);
      break;
    }
    default: {
      scatter(dim, cx, cy, cz, isl, "minecraft:sculk", 3, 1, 0);
      setBlock(dim, cx, cy + 1, cz, "minecraft:soul_lantern");
      placeChest(dim, cx + 1, cy + 1, cz);
    }
  }
}

function placeChest(dim, x, y, z) {
  if (!setBlock(dim, x, y, z, "minecraft:chest")) return;
  try {
    const container = dim.getBlock({ x, y, z })?.getComponent("minecraft:inventory")?.container;
    if (!container) return;
    const loot = [
      ["minecraft:echo_shard", 2],
      ["minecraft:sculk_catalyst", 1],
      ["minecraft:soul_lantern", 4],
      ["minecraft:diamond", 3],
      ["minecraft:phantom_membrane", 4],
      ["minecraft:blaze_powder", 2]
    ];
    loot.forEach(([id, count], i) => {
      try {
        container.setItem(i * 3 + 1, new ItemStack(id, count));
      } catch {}
    });
  } catch {}
}

function* buildBridge(dim, ax, ay, az, bx, bz, A, B) {
  const dx = bx - ax, dz = bz - az;
  const len = Math.max(Math.abs(dx), Math.abs(dz));
  const perpX = Math.abs(dx) >= Math.abs(dz) ? 0 : 1;
  const perpZ = 1 - perpX;
  let ops = 0;
  for (let i = 0; i <= len; i++) {
    const t = i / len;
    const x = Math.round(ax + dx * t);
    const z = Math.round(az + dz * t);
    const onA = insideIsland(x, z, A, ax, az) > 0.1;
    const onB = insideIsland(x, z, B, bx, bz) > 0.1;
    if (onA || onB) continue;
    const gap = noise(x * 7, z * 7) < 0.07;
    for (let w = 0; w <= 1; w++) {
      const wx = x + perpX * w, wz = z + perpZ * w;
      if (gap && w === 0) continue;
      setBlock(dim, wx, ay, wz, noise(wx, wz) < 0.15 ? "minecraft:cracked_deepslate_tiles" : "minecraft:deepslate_tiles");
      if (noise(wx + 3, wz + 5) < 0.12) setBlock(dim, wx - perpX + (w ? 2 * perpX : 0), ay + 1, wz - perpZ + (w ? 2 * perpZ : 0), "minecraft:deepslate_tile_wall");
    }
    if (++ops % 40 === 0) yield;
  }
}
